package com.campus.lostfound.repository;
import com.campus.lostfound.domain.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;import org.springframework.test.context.TestExecutionListeners;import org.springframework.test.context.TestExecutionListeners.MergeMode;import org.springframework.test.context.support.DependencyInjectionTestExecutionListener;import org.springframework.test.context.transaction.TransactionalTestExecutionListener;import org.springframework.test.context.jdbc.SqlScriptsTestExecutionListener;import java.time.LocalDate;import static org.junit.jupiter.api.Assertions.*;
@DataJpaTest @TestExecutionListeners(listeners={DependencyInjectionTestExecutionListener.class,TransactionalTestExecutionListener.class,SqlScriptsTestExecutionListener.class},mergeMode=MergeMode.REPLACE_DEFAULTS) class ReportVisibilityTest {
 @Autowired ItemReportRepository reports; @Autowired UserRepository users;
 @Test void activeLostAndFoundReportsAreRetrievableAcrossJoinedInheritance(){User student=users.save(new User("Test Student","visibility@example.edu","hash","T-1","Computing",Role.STUDENT));reports.save(new LostReport("Lost blue notebook","Blue cover","Books and Stationery","Main Library",LocalDate.now(),null,student,"10:00"));reports.save(new FoundReport("Found silver keys","Two keys","Accessories","Main Gate",LocalDate.now(),null,student,"11:00","Security","green keyring"));var active=reports.findAll().stream().filter(r->r.getStatus()==ReportStatus.ACTIVE).toList();assertEquals(2,active.size());assertTrue(active.stream().anyMatch(r->r.getType()==ReportType.LOST));assertTrue(active.stream().anyMatch(r->r.getType()==ReportType.FOUND));assertTrue(active.stream().allMatch(r->r.getReporter().getFullName().equals("Test Student")));}
}
